import{_ as s,o as e,c as a,a2 as i}from"./chunks/framework.DHmNT4rz.js";const k=JSON.parse('{"title":"SSO / SAML testing (local IdP)","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"guide/sso-testing.md","filePath":"guide/sso-testing.md","lastUpdated":null}'),o={name:"guide/sso-testing.md"};function d(n,t,l,r,h,p){return e(),a("div",null,[...t[0]||(t[0]=[i(`<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/docs/SSO-TESTING.md" target="_blank" rel="noreferrer"><code>docs/SSO-TESTING.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="sso-saml-testing-local-idp" tabindex="-1">SSO / SAML testing (local IdP) <a class="header-anchor" href="#sso-saml-testing-local-idp" aria-label="Permalink to &quot;SSO / SAML testing (local IdP)&quot;">​</a></h1><p>Reproducible manual verification of the console SSO settings panel and SP-initiated SAML login against a real Identity Provider. Automated SAML e2e is intentionally <strong>not</strong> run in CI (browser + IdP + cookies); see <a href="https://github.com/mathias7799/SaaSWeave/blob/main/apps/web/__e2e__/sso.spec.ts" target="_blank" rel="noreferrer">apps/web/<strong>e2e</strong>/sso.spec.ts</a>.</p><h2 id="test-idp-image" tabindex="-1">Test IdP image <a class="header-anchor" href="#test-idp-image" aria-label="Permalink to &quot;Test IdP image&quot;">​</a></h2><p><strong>Image:</strong> <a href="https://hub.docker.com/r/kristophjunge/test-saml-idp" target="_blank" rel="noreferrer"><code>kristophjunge/test-saml-idp:1.15</code></a></p><p>Chosen because it is a widely used, documented SimpleSAMLphp-based dev IdP with static demo users, env-driven SP configuration (<code>SIMPLESAMLPHP_SP_*</code>), and no extra wiring beyond Docker Compose. <strong>Do not use in production</strong> (static credentials and keys).</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ol><li><p>Main stack running (see <a href="/SaaSWeave/guide/local-stack">LOCAL-STACK.md</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># set BETTER_AUTH_SECRET (vp run auth:secret)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:up:build</span></span></code></pre></div></li><li><p>Start the opt-in IdP profile (does <strong>not</strong> start with default <code>docker compose up</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotenvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso-idp</span></span></code></pre></div><p>IdP UI: <code>http://localhost:\${SSO_IDP_PORT:-8081}/simplesaml</code> (admin password: <code>secret</code>).</p></li><li><p>Workspace on a plan that includes SSO (<code>scale</code> or <code>enterprise</code>) and the <code>sso</code> feature enabled for that org. New workspaces default to <code>starter</code> — upgrade via <strong>Admin → Organizations</strong> (or set <code>organization.plan_id</code> in Postgres) before the SSO settings panel appears.</p></li></ol><h2 id="service-provider-urls-better-auth" tabindex="-1">Service Provider URLs (Better Auth) <a class="header-anchor" href="#service-provider-urls-better-auth" aria-label="Permalink to &quot;Service Provider URLs (Better Auth)&quot;">​</a></h2><p>With default <code>.env.docker</code> URLs (<code>VITE_SERVER_URL=http://localhost:5000/server</code>), Better Auth mounts SSO under <code>/server/auth</code>. For provider id <code>local-saml</code> (default in <code>.env.docker.example</code>):</p><table tabindex="0"><thead><tr><th>Role</th><th>URL</th></tr></thead><tbody><tr><td>ACS (Assertion Consumer Service)</td><td><code>http://localhost:5000/server/auth/sso/saml2/sp/acs/local-saml</code></td></tr><tr><td>SP metadata (optional)</td><td><code>http://localhost:5000/server/auth/sso/saml2/sp/metadata/local-saml</code></td></tr></tbody></table><p>The compose <code>sso-idp</code> service pre-configures the test IdP with these values via <code>SSO_TEST_SP_*</code> env vars.</p><h2 id="identity-provider-metadata" tabindex="-1">Identity Provider metadata <a class="header-anchor" href="#identity-provider-metadata" aria-label="Permalink to &quot;Identity Provider metadata&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value (default port 8081)</th></tr></thead><tbody><tr><td>Metadata URL</td><td><code>http://localhost:8081/simplesaml/saml2/idp/metadata.php</code></td></tr><tr><td>Entity ID / Issuer</td><td><code>http://localhost:8081/simplesaml/saml2/idp/metadata.php</code></td></tr><tr><td>SSO URL (entry point)</td><td><code>http://localhost:8081/simplesaml/saml2/idp/SSOService.php</code></td></tr><tr><td>Certificate</td><td>X509 block inside metadata XML (see below)</td></tr></tbody></table><p>Fetch the signing certificate (<strong>manual</strong> — paste into the console textarea):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:8081/simplesaml/saml2/idp/metadata.php&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/.*&lt;ds:X509Certificate&gt;\\(.*\\)&lt;\\/ds:X509Certificate&gt;.*/\\1/p&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fold</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1s/^/-----BEGIN CERTIFICATE-----\\n/;$s/$/\\n-----END CERTIFICATE-----/&#39;</span></span></code></pre></div><h2 id="register-the-provider-in-the-console-manual" tabindex="-1">Register the provider in the console (<strong>manual</strong>) <a class="header-anchor" href="#register-the-provider-in-the-console-manual" aria-label="Permalink to &quot;Register the provider in the console (**manual**)&quot;">​</a></h2><ol><li>Sign in as workspace <strong>owner</strong> or <strong>admin</strong>.</li><li>Open <strong>Console → Settings</strong> (SSO panel visible only when <code>sso</code> is enabled for the org).</li><li>Register with these values (must match compose defaults):</li></ol><table tabindex="0"><thead><tr><th>Console field</th><th>Value</th></tr></thead><tbody><tr><td>Provider ID</td><td><code>local-saml</code></td></tr><tr><td>Domain</td><td><code>example.com</code></td></tr><tr><td>Issuer</td><td><code>http://localhost:8081/simplesaml/saml2/idp/metadata.php</code></td></tr><tr><td>SSO entry point</td><td><code>http://localhost:8081/simplesaml/saml2/idp/SSOService.php</code></td></tr><tr><td>Certificate</td><td>PEM from metadata (command above)</td></tr></tbody></table><ol start="4"><li>Click <strong>Register</strong> and confirm the provider appears in the list.</li></ol><blockquote><p><strong>Note:</strong> Better Auth uses the <strong>Issuer</strong> field as the SP entity ID when <code>spMetadata</code> is empty. The test IdP <code>SIMPLESAMLPHP_SP_ENTITY_ID</code> is set to the same IdP metadata URL so AuthnRequest issuer and IdP SP config align.</p></blockquote><h2 id="sp-initiated-login-manual" tabindex="-1">SP-initiated login (<strong>manual</strong>) <a class="header-anchor" href="#sp-initiated-login-manual" aria-label="Permalink to &quot;SP-initiated login (**manual**)&quot;">​</a></h2><p>Demo IdP user (from the image):</p><table tabindex="0"><thead><tr><th>Username</th><th>Password</th><th>Email</th></tr></thead><tbody><tr><td><code>user1</code></td><td><code>user1pass</code></td><td><code>user1@example.com</code></td></tr></tbody></table><p>The sign-in page SSO button does not send the email field to Better Auth. Start SP-initiated login with an API call (browser or terminal):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/sso-cookies.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/sso-cookies.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;email&quot;:&quot;user1@example.com&quot;,&quot;callbackURL&quot;:&quot;http://localhost:3000/app&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;http://localhost:5000/server/auth/sign-in/sso&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .url</span></span></code></pre></div><p>Open the printed URL in a browser (<strong>manual</strong>). At the IdP, sign in as <code>user1</code> / <code>user1pass</code>. After the POST to the ACS URL you should land on <code>http://localhost:3000/app</code> with an authenticated session.</p><p><strong>Verify:</strong></p><ul><li>Session exists (avatar / console loads).</li><li>User is provisioned into the workspace that registered the provider (org member with role <code>member</code> via Better Auth <code>organizationProvisioning</code>).</li><li>A second login with the same IdP user reuses the account (no duplicate user).</li></ul><h2 id="stop-the-idp" tabindex="-1">Stop the IdP <a class="header-anchor" href="#stop-the-idp" aria-label="Permalink to &quot;Stop the IdP&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotenvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso-idp</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>SSO panel missing</td><td>Org plan <code>scale</code>/<code>enterprise</code>; <code>sso</code> feature on at <code>/admin/features</code></td></tr><tr><td>IdP “unknown SP”</td><td><code>SSO_TEST_SP_ENTITY_ID</code> matches <strong>Issuer</strong> in console; provider id matches ACS path</td></tr><tr><td>ACS 404</td><td><code>VITE_SERVER_URL</code> must be <code>http://localhost:5000/server</code>; provider id spelling</td></tr><tr><td>Port clash with imgproxy</td><td>Change <code>SSO_IDP_PORT</code> (default <code>8081</code>; imgproxy uses <code>8080</code>)</td></tr><tr><td>Certificate errors</td><td>Re-copy PEM from live metadata; include <code>BEGIN</code>/<code>END</code> lines</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/SaaSWeave/guide/local-stack">LOCAL-STACK.md</a> — full Docker stack</li><li><a href="/SaaSWeave/reference/packages/auth">packages/auth/README.md</a> — Better Auth + <code>@better-auth/sso</code></li></ul>`,35)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
